  },
  {
    "flavor_text": "It’s drowsy in daytime, but flies off in the evening in\nbig groups. No one knows where they go.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "alpha-sapphire",
      "url": "https://pokeapi.co/api/v2/version/26/"
    }
  },
  {
    "flavor_text": "There was once an incident in which a man\ntook a trip riding a Drifblim, only to go missing.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sun",
      "url": "https://pokeapi.co/api/v2/version/27/"
    }
  },
  {
    "flavor_text": "Even while under careful observation, large\nflocks of Drifblim flying at dusk will inexplicably\ndisappear from view.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "moon",
      "url": "https://pokeapi.co/api/v2/version/28/"
    }
  },
  {
    "flavor_text": "There’s a rumor that if you catch a Drifblim\nfloating on the wind at dusk, you’ll be carried\naway to the afterlife.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-sun",
      "url": "https://pokeapi.co/api/v2/version/29/"
    }
  },
  {
    "flavor_text": "The raw material for the gas inside its body\nis souls. When its body starts to deflate, it’s\nthought to carry away people and Pokémon.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-moon",
      "url": "https://pokeapi.co/api/v2/version/30/"
    }
  },
  {
    "flavor_text": "Some say this Pokémon is a collection of souls\nburdened with regrets, silently drifting through\nthe dusk.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sword",
      "url": "https://pokeapi.co/api/v2/version/33/"
    }
  },
  {
    "flavor_text": "It grabs people and Pokémon and carries them\noff somewhere. Where do they go?\nNobody knows.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "shield",
      "url": "https://pokeapi.co/api/v2/version/34/"
    }
  },
  {
    "flavor_text": "It drifts along at dusk, perfectly silent. Its transient, melancholy\naspect touches some people deeply—every so often, one will\ncome upon a song or poem devoted to Drifblim.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "legends-arceus",
      "url": "https://pokeapi.co/api/v2/version/39/"
    }
  }
]

