      "url": "https://pokeapi.co/api/v2/version/30/"
    }
  },
  {
    "flavor_text": "If both of Buneary’s ears are rolled up, something\nis wrong with its body or mind. It’s a sure sign the\nPokémon is in need of care.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
