      "url": "https://pokeapi.co/api/v2/version/33/"
    }
  },
  {
    "flavor_text": "Buneary can attack by rolling up their ears and\nthen striking with the force created by unrolling\nthem. This attack becomes stronger with training.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "shield",
      "url": "https://pokeapi.co/api/v2/version/34/"
    }
  },
  {
    "flavor_text": "My hypothesis as to why Buneary rolls up its ears is that its\nhearing is far too keen. I surmise that the Pokémon protects its\nhearing by limiting the sound that may enter its ears.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "legends-arceus",
      "url": "https://pokeapi.co/api/v2/version/39/"
    }
  }
]

