[
  {
    "flavor_text": "When it finds a trace of its prey, it patiently\nstakes out the location...but it’s always snoozing\nby nightfall.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sun",
      "url": "https://pokeapi.co/api/v2/version/27/"
    }
  },
  {
    "flavor_text": "It adores having Rattata and Raticate for dinner,\nbut as it’s diurnal, it never encounters them.\nThis Pokémon boasts incredible patience.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "moon",
      "url": "https://pokeapi.co/api/v2/version/28/"
    }
  },
  {
    "flavor_text": "Although it wasn’t originally found in Alola, this\nPokémon was brought over a long time ago\nwhen there was a huge Rattata outbreak.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-sun",
      "url": "https://pokeapi.co/api/v2/version/29/"
    }
  },
  {
    "flavor_text": "Patient by nature, this Pokémon loses control of\nitself and pounces when it spots its favorite\nmeal—Rattata!",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-moon",
      "url": "https://pokeapi.co/api/v2/version/30/"
    }
  }
]

[
  {
    "flavor_text": "It zips around, on sharp lookout for an opening.\nIt concentrates electrical energy within its large\njaws and uses it to zap its enemies.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sun",
      "url": "https://pokeapi.co/api/v2/version/27/"
    }
  },
  {
    "flavor_text": "It produces electricity via an electrical organ in\nits abdomen. It overwhelms bird Pokémon with\nshocking beams of electrical energy.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "moon",
      "url": "https://pokeapi.co/api/v2/version/28/"
    }
  },
  {
    "flavor_text": "It has an organ that generates electricity in its\nabdomen. It concentrates energy in its strong\njaws and fires off powerful jolts of electricity.",
