    }
  },
  {
    "flavor_text": "Vikavolt flusters opponents with acrobatic\nflying maneuvers. This creates an opening for\nit to deliver an electric beam attack.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-moon",
      "url": "https://pokeapi.co/api/v2/version/30/"
    }
  },
  {
    "flavor_text": "It builds up electricity in its abdomen, focuses it\nthrough its jaws, and then fires the electricity off\nin concentrated beams.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sword",
      "url": "https://pokeapi.co/api/v2/version/33/"
    }
  },
  {
    "flavor_text": "If it carries a Charjabug to use as a spare battery,\na flying Vikavolt can rapidly fire high-powered\nbeams of electricity.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "shield",
      "url": "https://pokeapi.co/api/v2/version/34/"
    }
  }
]

