      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-moon",
      "url": "https://pokeapi.co/api/v2/version/30/"
    }
  },
  {
    "flavor_text": "Only female Salazzle exist. They emit a gas laden\nwith pheromones to captivate male Salandit.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
