    "version": {
      "name": "sword",
      "url": "https://pokeapi.co/api/v2/version/33/"
    }
  },
  {
    "flavor_text": "The winner of competitions between Salazzle\nis decided by which one has the most male\nSalandit with it.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "shield",
      "url": "https://pokeapi.co/api/v2/version/34/"
    }
  }
