[
  {
    "flavor_text": "Its actual appearance is unknown. A scholar\nwho saw what was under its rag was\noverwhelmed by terror and died from the shock.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sun",
      "url": "https://pokeapi.co/api/v2/version/27/"
    }
  },
  {
    "flavor_text": "A lonely Pokémon, it conceals its terrifying\nappearance beneath an old rag so it can get\ncloser to people and other Pokémon.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "moon",
      "url": "https://pokeapi.co/api/v2/version/28/"
    }
  },
  {
    "flavor_text": "Although it’s a quiet, lonely Pokémon, if you try\nto look at what’s under its rag, it will become\nagitated and resist violently.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-sun",
      "url": "https://pokeapi.co/api/v2/version/29/"
    }
  },
  {
    "flavor_text": "A gust of wind revealed what hides under this\nPokémon’s rag to a passing Trainer, who went\nhome and died painfully that very night.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-moon",
      "url": "https://pokeapi.co/api/v2/version/30/"
    }
  },
  {
    "flavor_text": "It wears a rag fashioned into a Pikachu costume\nin an effort to look less scary. Unfortunately,\nthe costume only makes it creepier.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sword",
      "url": "https://pokeapi.co/api/v2/version/33/"
    }
  },
  {
    "flavor_text": "There was a scientist who peeked under\nMimikyu’s old rag in the name of research.\nThe scientist died of a mysterious disease.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "shield",
      "url": "https://pokeapi.co/api/v2/version/34/"
    }
  }
]

