      "url": "https://pokeapi.co/api/v2/version/29/"
    }
  },
  {
    "flavor_text": "It appears in towns and plays with the children.\nDrampa will protect kids when they’re in danger,\nso their moms don’t have to worry.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "ultra-moon",
      "url": "https://pokeapi.co/api/v2/version/30/"
    }
  },
  {
    "flavor_text": "The mountains it calls home are nearly two miles\nin height. On rare occasions, it descends to play\nwith the children living in the towns below.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "sword",
      "url": "https://pokeapi.co/api/v2/version/33/"
    }
  },
  {
    "flavor_text": "Drampa is a kind and friendly Pokémon—up until\nit’s angered. When that happens, it stirs up a\ngale and flattens everything around.",
    "language": {
      "name": "en",
      "url": "https://pokeapi.co/api/v2/language/9/"
    },
    "version": {
      "name": "shield",
      "url": "https://pokeapi.co/api/v2/version/34/"
    }
  }
]

